effect.shader:
float nivel(float x) {
    float faixa = inputWhite - inputBlack;
    float t = faixa != 0.0 ? clamp((x - inputBlack) / faixa, 0.0, 1.0) : (x >= inputBlack ? 1.0 : 0.0);
    t = gamma > 0.0 ? pow(t, 1.0 / gamma) : (t >= 1.0 ? 1.0 : 0.0);
    return clamp(outputBlack + (outputWhite - outputBlack) * t, 0.0, 1.0);
}

void main() {
    ivec2 T = textureSize(inputImg, 0);
    vec4 c = texelFetch(inputImg, ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0)), 0);
    if (channel == 0) c.rgb = vec3(nivel(c.r), nivel(c.g), nivel(c.b));
    else if (channel == 1) c.r = nivel(c.r);
    else if (channel == 2) c.g = nivel(c.g);
    else if (channel == 3) c.b = nivel(c.b);
    else c.a = nivel(c.a);
    fragColor = c;
}
